import os

# ── AccountBase.java (Basisklasse) ────────────────────────────────────────
account_base_code = '''abstract class AccountBase {
    protected final String accountHolder;
    protected double balance;

    public AccountBase(String accountHolder) {
        this(accountHolder, 0.0);
    }

    public AccountBase(String accountHolder, double initialBalance) {
        this.accountHolder = accountHolder;
        this.balance = initialBalance;
    }

    public final String getAccountHolder() {
        return accountHolder;
    }

    public final double getBalance() {
        return balance;
    }

    public abstract void deposit(double amount);

    public abstract boolean withdraw(double amount);
}'''
with open('AccountBase.java', 'w') as f:
    f.write(account_base_code)

# ── BankAccount.java (Studenten-Code) ──────────────────────────────────────
student_answer = """{{ STUDENT_ANSWER | e('py') }}"""
with open('BankAccount.java', 'w') as f:
    f.write(student_answer)

# ── Test.java (Testfall) ───────────────────────────────────────────────────
testcode = """{{ TEST.testcode | e('py') }}"""
test_class = '''public class Test {
    public static void main(String[] args) throws Exception {
        ''' + testcode + '''
    }
}'''
with open('Test.java', 'w') as f:
    f.write(test_class)

# ── Kompilierung ────────────────────────────────────────────────────────────
ret = os.system('javac -J-Xmx128m -J-XX:CompressedClassSpaceSize=64m -encoding UTF-8 AccountBase.java BankAccount.java Test.java 2>&1')
if ret == 0:
    os.system('java -Xmx128m -XX:CompressedClassSpaceSize=64m -cp . Test')

question.answer:
public class BankAccount extends AccountBase {

    // Konstruktor 1: nur mit Kontoinhaber (Startguthaben 0.0)
    public BankAccount(String accountHolder) {
        super(accountHolder);
    }

    // Konstruktor 2: mit Kontoinhaber und Startguthaben
    public BankAccount(String accountHolder, double initialBalance) {
        super(accountHolder, initialBalance);
    }

    @Override
    public void deposit(double amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    @Override
    public boolean withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            return true;
        }
        return false;
    }

    @Override
    public String toString() {
        return "Kontoinhaber: " + accountHolder + ", Saldo: " + balance + "€";
    }
}

